"""Builder registry: generators turn a Registry into a deployable artifact (text)."""
from __future__ import annotations

import datetime as dt
from typing import Callable

from cvc.access.model import Registry

Builder = Callable[[Registry, dt.date], str]
BUILDERS: dict[str, Builder] = {}

GENERATED_HEADER = (
    "# GENERATED by `cvc-access build {name}` from access/registry.yaml.\n"
    "# DO NOT EDIT: change the registry and regenerate.\n"
)


def register_builder(name: str) -> Callable[[Builder], Builder]:
    """Decorator: `@register_builder("mosquitto")` makes `cvc-access build mosquitto` work."""
    def deco(fn: Builder) -> Builder:
        BUILDERS[name] = fn
        return fn
    return deco
